-- ============================================================
-- MAKALE QUIZ SORULARI — gövdeden tabloya
-- ============================================================
-- Üreten: scripts/quiz-sorulari-sql-uret.mjs (elle düzenleme, yeniden üret)
-- 170 soru · 26 makale
--
-- Neden: makale içindeki "mini quiz" kaynak dosyada duruyordu; hiçbir yere
-- yazmıyor, XP vermiyordu. XP kazandıran quiz ise quiz_questions'tan okuyor
-- ama tabloda yalnız 33 soru vardı ve 14 makalenin hiç sorusu yoktu. Mini
-- quiz kaldırılıp her yerde XP'li altyapıya geçiliyor; bu dosya soruları
-- taşıyor ki içerik kaybolmasın.
--
-- GÜVENLİ: her satır `where not exists` ile korunuyor — tekrar tekrar
-- çalıştırabilirsin, aynı soru iki kez eklenmez. Mevcut satırlara DOKUNMAZ
-- (article_quiz_answers onlara on delete cascade ile bağlı; silmek
-- kullanıcıların XP kaydını da silerdi).
--
-- ⚠ YAN ETKİ: Günün Sorusu havuzu da quiz_questions'tan besleniyor
-- (active=true olan hepsi). Bu dosya havuzu ~33'ten ~203'e çıkarır —
-- havuzun ince olması zaten bilinen bir sorundu, çeşitlilik artar. Günün
-- sorusu `dayNumber % toplam` ile seçildiği için sıra da değişir.
-- ============================================================

insert into public.quiz_questions (question, options, correct_index, explanation, article_slug)
select v.question, v.options::jsonb, v.correct_index, v.explanation, v.article_slug
from (values
    ('Priskos’un 449’da otağda gördüğü sofrada Atilla neyden yiyip içiyordu?', '["Altın kadeh ve gümüş tabak","Tahta kadeh ve tahta tabak","Cam kadeh","Kaynaklar bundan hiç söz etmez"]', 1, 'Konuklara altın ve gümüş verilmişti; kağan tahtadan yedi ve içti. Süssüzlük bir yoksulluk değil, bir tercihti.', 'atilla'),
    ('Kavimler Göçü ne zaman başladı?', '["Atilla tahta çıktıktan sonra","Catalaunum’dan sonra","Atilla doğmadan önce","476’da Roma yıkılınca"]', 2, 'Zincir ~370’te İtil’in geçilmesiyle başladı, 378’de Edirne’yle hızlandı. Atilla bu göçün yarattığı dünyayı devraldı.', 'atilla'),
    ('Atilla ve Bleda’nın 434’te BİRLİKTE kağan olması ne anlama gelir?', '["Bir veraset krizi yaşandığını","İkili teşkilatın olağan işleyişini","Roma’nın dayattığı bir düzeni","Kurultayın toplanamadığını"]', 1, 'Bozkır devletinde sağ/sol kanat ve iki hükümdar normal düzendir. Geniş coğrafyayı tek merkezden yönetmenin çözümüdür.', 'atilla'),
    ('447’de surların önüne gelen Atilla neden Konstantinopolis’i kuşatmadı?', '["Ordusu yetersizdi","Şehri almak bir kerelik ganimet, ayakta bırakmak her yıl haraç demekti","Papa onu ikna etti","Kış bastırdı"]', 1, 'Hedef şehir değil akıştı. Yıkmamak yıkmaktan kârlıydı — ayrıca sur 60 günde onarılmış, hendek ve dış hat güçlendirilmişti.', 'atilla'),
    ('Jordanes’in Catalaunum için verdiği 165.000 ölü sayısı neden şüpheyle karşılanır?', '["Jordanes muharebeye katılmadığı için","Lojistik imkânsız olduğu için: o kadar insanın tahılı, suyu ve yol genişliği tutmuyor","Roma kaynakları hep abartır","Sayı sonradan eklendiği için"]', 1, 'Bir orduyu yürüten şey tahıl, su ve yoldur. Sayıyı sıfatla değil aritmetikle sınarsınız — makaledeki hesaplayıcı tam da bunu yapıyor.', 'atilla'),
    ('Batı Roma İmparatorluğu’nu kim sona erdirdi?', '["Atilla, 452’de","Odoacer, 476’da","Aetius, 454’te","Vizigotlar, 410’da"]', 1, 'Atilla öleli 23 yıl olmuştu. Son imparatoru tahttan indiren, Roma ordusunun kendi subayı Odoacer’di.', 'atilla'),
    ('Bulgar Hanları Nominaliası’ndaki "İrnik" kimle özdeşleştirilir?', '["Atilla’nın kardeşi Bleda","Atilla’nın oğlu Ernak","Amcası Rua","Gepid kralı Ardaric"]', 1, 'Priskos’un da adını verdiği Ernak, Atilla’nın en küçük oğlu. Bulgar hanedan listesi soyunu Dulo üzerinden buraya bağlar.', 'atilla'),
    ('"Tanrı’nın Kırbacı" adı ne zaman ortaya çıktı?', '["Atilla’nın kendi kullandığı unvandı","Priskos otağda duymuştu","Sonraki yüzyılların Hristiyan yorumudur","Kurultayda verilmişti"]', 2, 'Çağdaş hiçbir kaynak ona böyle demez. Bu ad Atilla hakkında değil, ona bakanın teolojisi hakkında bilgi verir.', 'atilla'),
    ('Augustus MÖ 27’de Senato’ya girip "her şeyi geri veriyorum" dedi. Bu neydi?', '["Gerçek bir emeklilik","Bir sahne — yetkiyi başka adlarla geri aldı","Cumhuriyet’in gerçek dönüşü","Bir zayıflık anı"]', 1, 'Yetkileri gerçekten bıraktı, ama Senato yalvarınca "isteksizce" geri aldı — sadece bir kısmını, geçici olarak, devlet için. Reddediş senaryonun parçasıydı. Cumhuriyet’i yıkmadı, içine yerleşti.', 'augustus'),
    ('Augustus’un gücü resmen neye dayanıyordu?', '["Kral unvanına","Ömür boyu diktatörlüğe","Cumhuriyet’in eski makamlarının tek vücutta toplanmasına","Senato’nun onu imparator seçmesine"]', 2, 'Tribün dokunulmazlığı + prokonsül imperium’u + Pontifex Maximus + Pater Patriae. Hiçbiri kraliyet unvanı değil; hepsi eski, meşru makamlar. O sadece hepsini aynı anda topladı. En tehlikeli güç, adı olmayan güçtür.', 'augustus'),
    ('Teutoburg’dan sonra XVII, XVIII ve XIX lejyon numaralarına ne oldu?', '["Yeniden kuruldular","Başka lejyonlara verildi","Bir daha asla kullanılmadı","İsimleri değiştirildi"]', 2, 'Roma lejyon numaralarını geri dönüştürürdü, ama bu üçü imparatorluğun sonuna kadar boş kaldı. Bazı anıtlar boşluktan yapılır.', 'augustus'),
    ('Augustus’un ölüm döşeğindeki son "resmî" sözü neydi?', '["\"Zar atıldı\"","\"Roma’yı mermerden bıraktım\"","\"Oyun bitti, alkışlayın\"","\"Lejyonlarımı geri ver\""]', 2, '"Acta est fabula, plaudite" — Roma komedilerinin kapanış repliği. Elli yıl "sıradan bir vatandaşım" diyen adam, ölmeden önce açıkça "bu bir oyundu" dedi. "Zar atıldı" ise Caesar’ın cümlesiydi — biri kumarbaz, biri aktör.', 'augustus'),
    ('Caesar ile Augustus arasındaki temel fark neydi?', '["Augustus daha iyi bir generaldi","Caesar tacı istedi ve öldürüldü; Augustus istemiyormuş gibi yapıp her şeyi aldı","Augustus Cumhuriyet’i gerçekten geri getirdi","Caesar daha uzun yaşadı"]', 1, 'Caesar tacı istediği için 23 bıçak yedi. Augustus tacı iterek her şeyi aldı, iki yüzyıl barış kurdu ve tanrı ilan edildi. Fark, "Zar atıldı" ile "Oyun bitti, alkışlayın" arasındaki fark.', 'augustus'),
    ('Bağırsaklara "ikinci beyin" denmesinin sebebi nedir?', '["Kafatasında ikinci bir beyin olması","Bağırsak duvarında ~500 milyon nöronluk kendi sinir ağı bulunması","İki ayrı bağırsak olması","Beyinle aynı şekle sahip olması"]', 1, null, 'bagirsak'),
    ('Vücuttaki serotoninin yaklaşık ne kadarı bağırsakta üretilir?', '["hiç","%5","%30","%90"]', 3, null, 'bagirsak'),
    ('Bağırsak ile beyin arasındaki ana iletişim siniri hangisidir?', '["Siyatik sinir","Koku siniri","Optik sinir","Vagus siniri"]', 3, null, 'bagirsak'),
    ('"İçime doğdu" türü içgüdüsel kararlarda beynin hangi yeteneği rol oynar?', '["Kas hafızası","Görme keskinliği","İnterosepsiyon (iç beden sinyallerini algılama)","Denge"]', 2, null, 'bagirsak'),
    ('Mikrobiyom–ruh hali ilişkisini gösteren çarpıcı deney hangisidir?', '["Stresli farelerin bağırsak mikrobunu sağlıklı farelere nakletmek (FMT)","Beyin ameliyatı","Açlık deneyi","Aya canlı göndermek"]', 0, null, 'bagirsak'),
    ('Bağırsak sağlığı için en temel besin grubu hangisidir?', '["Lif (sebze/meyve/tahıl)","Kızartma","Beyaz un","Şeker"]', 0, null, 'bagirsak'),
    ('Vagus sinirini doğal yolla uyarıp sakinleşmenin bir yolu nedir?', '["Nefesi uzun süre tutmak","Kalkıp koşmak","Hızlı ve sığ nefes","Yavaş, derin nefes (uzun nefes verme)"]', 3, null, 'bagirsak'),
    ('Açlık hissini tetikleyen, boş midede salgılanan hormon hangisidir?', '["Serotonin","Leptin","Ghrelin","İnsülin"]', 2, null, 'bagirsak'),
    ('Heyecanlanınca midemizde “kelebek” hissinin sebebi nedir?', '["Midede gerçek kelebek olması","Fight-or-flight ile kanın sindirimden kaslara yönelmesi","Aşırı açlık","Vitamin eksikliği"]', 1, null, 'bagirsak'),
    ('Bakteriyofaj nedir?', '["Bakterileri enfekte eden bir virüs","Bir antibiyotik türü","Bir mantar","İnsanı enfekte eden bir bakteri"]', 0, null, 'bakteriyofaj'),
    ('"Faj" adı hangi kökten gelir?', '["Yunanca phagein (\"yemek\")","Rusça \"küçük\"","Gürcüce \"avcı\"","Latince \"ışık\""]', 0, null, 'bakteriyofaj'),
    ('Gezegende tahminen kaç bakteriyofaj vardır?', '["1 milyon","10⁴","10⁹","10³¹"]', 3, null, 'bakteriyofaj'),
    ('Litik döngünün sonunda bakteriye ne olur?', '["Antibiyotiğe dönüşür","Sağlıklı kalır","Lizin enzimiyle patlar ve yüzlerce faj saçılır","Daha hızlı çoğalır"]', 2, null, 'bakteriyofaj'),
    ('Lizojenik döngüde faj DNA''sı ne yapar?', '["Anında yok olur","Antibiyotik üretir","Hücreyi hemen patlatır","Bakterinin kromozomuna eklenip profaj olarak gizlenir"]', 3, null, 'bakteriyofaj'),
    ('CRISPR aslında doğada neyin parçasıdır?', '["Bir antibiyotik","Bir faj silahı","Bakterilerin fajlara karşı geliştirdiği bağışıklık sistemi","İnsan bağışıklığı"]', 2, null, 'bakteriyofaj'),
    ('Dünyanın ilk faj enstitüsü nerede kuruldu?', '["Tiflis (Gürcistan)","New York","Paris","Londra"]', 0, null, 'bakteriyofaj'),
    ('Fajın antibiyotiğe göre temel avantajı nedir?', '["Daha ucuz olması","Yalnızca hedef bakteriyi öldürüp mikrobiyomu koruması","Hiç direnç oluşturmaması","Bitkileri de tedavi etmesi"]', 1, null, 'bakteriyofaj'),
    ('The Lancet''e göre 2019''da doğrudan antibiyotik direncine bağlı kaç ölüm gerçekleşti?', '["~10 bin","~1,27 milyon","~100","~50 milyon"]', 1, null, 'bakteriyofaj'),
    ('Bir transistör temelde ne yapar?', '["Akımı geçirir (1) veya geçirmez (0) — minik bir anahtar","Isıyı depolar","Ses üretir","Işık üretir"]', 0, 'Milyarlarca transistörü doğru birleştirince toplama, karşılaştırma gibi mantık işlemleri ortaya çıkar.', 'bilgisayar'),
    ('CPU ile GPU arasındaki temel fark nedir?', '["İkisi aynıdır","GPU daha yavaştır","CPU az sayıda güçlü çekirdek, GPU binlerce basit çekirdek içerir","CPU görüntü çizemez"]', 2, 'CPU karmaşık sıralı işler için; GPU aynı basit işi aynı anda binlerce veri üzerinde yapmak (paralel işleme) için idealdir.', 'bilgisayar'),
    ('RAM''in “uçucu (volatile)” olması ne demektir?', '["Elektrik kesilince içindeki her şey silinir","Asla dolmaz","Sadece oyunlarda çalışır","Çok ısınır"]', 0, 'Bu yüzden kaydetmeden bilgisayar kapanırsa belgeni kaybedersin — o veri RAM''deydi, kalıcı diske yazılmamıştı.', 'bilgisayar'),
    ('DDR (Double Data Rate) ismi nereden gelir?', '["İki çekirdeği olduğu için","İki voltaj kullandığı için","İki kat pahalı olduğu için","Veriyi saatin hem yükselen hem alçalan kenarında taşıdığı için"]', 3, 'Her saat tıkında bir yerine iki kez veri aktarır — bu yüzden “çift veri hızı”.', 'bilgisayar'),
    ('SSD''nin HDD''ye göre en temel farkı nedir?', '["Daha ucuzdur","Hiç hareketli parçası yoktur (flash çipi kullanır)","Veriyi kalıcı tutmaz","Daha sesli çalışır"]', 1, 'HDD dönen manyetik plak + kafa kullanır; SSD elektronik NAND flash. Bu yüzden SSD çok daha hızlı, sessiz ve dayanıklıdır.', 'bilgisayar'),
    ('Mikrofon ile hoparlörün ilişkisi nedir?', '["Alakasızdırlar","Aynı fizik prensibinin (manyetizma ↔ hareket) iki yöne çalıştırılmış hâlidir","İkisi de ışık kullanır","Hoparlör sesi elektriğe çevirir"]', 1, 'Mikrofon: ses → titreşim → akım. Hoparlör: akım → manyetik kuvvet → hareket → ses. Bir hoparlörü mikrofon gibi bile kullanabilirsin.', 'bilgisayar'),
    ('Tek tek gönderilen elektronlar ekranda ne oluşturur?', '["Tek bir nokta","Hiçbir şey","İki basit yığın","Girişim şeritleri (aydınlık-karanlık bantlar)"]', 3, 'Her elektron tek bir noktaya çarpar ama binlercesi birikince girişim deseni ortaya çıkar — her biri sanki kendisiyle girişim yapar.', 'cift-yarik'),
    ('Hangi yarıktan geçtiğini ölçmeye başlarsan ne olur?', '["Desen daha net çıkar","Girişim kaybolur, iki bant belirir","Elektron durur","Değişmez"]', 1, 'Yol bilgisi kaydedildiği an dalga davranışı yok olur; elektron “uslu bir parçacık” gibi davranır.', 'cift-yarik'),
    ('Buradaki “gözlem/ölçüm” ne demektir?', '["Bir insanın gözüyle bakması","Bilincin gerçekliği yaratması","Sistemin çevresiyle etkileşip yol bilgisinin fiziksel kaydedilmesi","Işığın açılması"]', 2, 'Kimsenin bakması gerekmez; bilgi ortamda iz bırakacak şekilde kaydedildiği an desen bozulur. Buna dekoherans denir.', 'cift-yarik'),
    ('de Broglie''nin λ = h/p formülü neyi açıklar?', '["Neden atomlar kararlıdır","Elektronun kütlesini","Neden ışık hızlıdır","Neden büyük nesneler dalga gibi davranmaz (dalga boyları çok küçük)"]', 3, 'Momentum büyüdükçe dalga boyu küçülür; futbol topunun dalga boyu ölçülemeyecek kadar minik kalır.', 'cift-yarik'),
    ('Girişim desenini yok eden asıl şey nedir?', '["Yarıkların kapanması","İnsan bilinci","Bilginin çevreye yayılması (dekoherans)","Elektronun yavaşlaması"]', 2, 'Elektron, yol bilgisini taşıyan aygıtla dolanır; bu dolanıklık bir kez oluşunca girişim geri gelmez.', 'cift-yarik'),
    ('60 karbon atomlu C60 molekülleriyle yapılan deneyde ne görüldü?', '["Girişim deseni — koca moleküller de dalga gibi davrandı","Moleküller parçalandı","Sadece ısı","Hiç girişim yok"]', 0, '1999''da Zeilinger ekibi bunu gösterdi; sonra sınır 2000+ atoma taşındı.', 'cift-yarik'),
    ('Doğal seçilimde “en uyumlu birey” kimdir?', '["En uzun yaşayan","En zeki olan","En güçlü ve en iri olan","Ortamına en iyi uyup en çok yavru bırakan"]', 3, 'Uyum = ortama uygunluk ve üreme başarısı; kas ya da zekâ şart değil.', 'dogal-secilim'),
    ('Bir popülasyonda hiç çeşitlilik yoksa ne olur?', '["Seçilim daha hızlı işler","Doğal seçilim işleyemez — seçecek bir fark yoktur","Mutasyonlar durur","Tüm bireyler ölür"]', 1, 'Seçilim var olan farklar arasından seçer. Fark yoksa süreç durur.', 'dogal-secilim'),
    ('Aslında “evrimleşen” nedir?', '["Ortam, kendi başına","Tek bir birey, yaşamı boyunca","Popülasyon, nesiller boyunca","Sadece DNA, anında"]', 2, 'Birey yaşamı boyunca evrimleşmez; değişen, popülasyondaki özellik oranıdır.', 'dogal-secilim'),
    ('Antibiyotik direncinin yayılması neyin örneğidir?', '["Gerçek zamanlı doğal seçilim","Genetik sürüklenme","Rastgele şans","Bireysel öğrenme"]', 0, 'Dirençliler çoğalır, duyarlılar elenir — gözlemlenebilir doğal seçilim.', 'dogal-secilim'),
    ('Mutasyon ile seçilim arasındaki ilişki nedir?', '["Mutasyon rastgeledir; seçilim rastgele değildir","Seçilim rastgeledir; mutasyon yönlüdür","İkisi de rastgeledir","İkisi de yönlüdür"]', 0, 'Mutasyonlar yönsüz oluşur; hangi varyantın yayılacağını ortam belirler.', 'dogal-secilim'),
    ('Biber güvesinin koyu formu neden çoğaldı?', '["Koyu renk daha hızlı uçtuğu için","Tesadüfen","Daha sıcak olduğu için","Kurumlu ağaçlarda kuşlardan saklanıp daha çok ürediği için"]', 3, 'Kararmış ağaçlarda koyu güveler saklandı, daha çok üredi.', 'dogal-secilim'),
    ('Bir ambulans yanından geçerken aslında değişen nedir?', '["Sesin sana ulaşma biçimi (senin duyduğun frekans)","Havanın sıcaklığı","Sirenin ses düzeyi","Sirenin gerçek frekansı"]', 0, null, 'doppler'),
    ('Kaynak sana yaklaşırken dalgalara ne olur?', '["Tamamen durur","Gerilir, frekans düşer","Sıkışır, frekans yükselir (tizleşir)","Hiçbir şey olmaz"]', 2, null, 'doppler'),
    ('Buys Ballot 1845 deneyinde Doppler etkisini neyle kanıtladı?', '["Bir teleskopla","Trende kesintisiz nota çalan trompetçilerle","Bir diyapazonla","Şimşekle"]', 1, null, 'doppler'),
    ('Işıkta "maviye kayma" ne anlama gelir?', '["Kaynak bizden uzaklaşıyor","Kaynak bize yaklaşıyor (dalga boyu kısalır)","Kaynak duruyor","Kaynak ısınıyor"]', 1, null, 'doppler'),
    ('Evrenin genişlediği fikri hangi gözlemden doğdu?', '["Güneş lekelerinden","Meteor yağmurlarından","Ayın evrelerinden","Uzak galaksilerin kırmızıya kaymasından (Hubble, 1929)"]', 3, null, 'doppler'),
    ('İlk ötegezegen 51 Pegasi b nasıl bulundu?', '["Tesadüfen","Doğrudan fotoğrafla","Yıldızın Doppler salınımıyla (ışığının ileri-geri kayması)","Radyo patlamasıyla"]', 2, null, 'doppler'),
    ('Polis radarı hızı nasıl ölçer?', '["Motor sesinden","Far parlaklığından","Lastik izinden","Araçtan yansıyan dalganın Doppler kaymasından"]', 3, null, 'doppler'),
    ('Doppler etkisi ile ses patlaması (sonic boom) farkı nedir?', '["Ses patlaması, kaynak ses hızına ulaşıp şok konisi oluşturunca olur; Doppler ise frekansı kaydırır","Doppler sadece uçaklarda olur","Ses patlaması sessizdir","İkisi aynıdır"]', 0, null, 'doppler'),
    ('Ambulans geçerken ses nasıl değişir?', '["Hiç değişmez","Önce kalın sonra tiz olur","Yavaş yavaş kalınlaşır","Tizden kalına KESKİN bir basamakla düşer (geçiş anında)"]', 3, null, 'doppler'),
    ('Dünya yaklaşık kaç yaşında?', '["45,4 milyar yıl","4,54 milyon yıl","4,54 milyar yıl","454 milyon yıl"]', 2, 'Yaş, değişmeden kalmış göktaşları radyometrik tarihlenerek ~4,54 milyar yıl bulunur.', 'dunya'),
    ('Demir ve nikel neden gezegenin merkezinde toplandı?', '["Hep oradaydılar","Manyetik çekim onları çekti","Gezegen eridi, ağır metaller dibe battı (demir felaketi)","Volkanlar onları içeri pompaladı"]', 2, 'Erimiş kaya okyanusunda yoğun demir/nikel merkeze battı, hafif silikatlar yükseldi — gezegensel farklılaşma.', 'dunya'),
    ('İç çekirdek, dış çekirdekten sıcak olmasına rağmen neden KATIDIR?', '["Farklı bir metal olduğu için","Manyetik alan dondurur","Daha soğuk olduğu için","Muazzam basınç demir atomlarını katı tutar"]', 3, 'Sıcaklık eritmek ister ama atmosferin ~3,5 milyon katı basınç katı tutar; basınç kazanır.', 'dunya'),
    ('Dünya''nın manyetik alanını ne üretir?', '["Güneş rüzgârı","Atmosferdeki elektrik","Çekirdekteki dev bir çubuk mıknatıs","Sıvı dış çekirdekteki demirin dönerek akması (jeodinamo)"]', 3, 'Elektriği ileten erimiş demirin dönüşü akım üretir; akım alanı, alan akımı besler — jeodinamo.', 'dunya'),
    ('En geniş kabul gören açıklamaya göre Ay nasıl oluştu?', '["Dünya tarafından yakalandı","Mars büyüklüğünde Theia''nın Dünya''ya çarpmasıyla","Dünya''yla aynı anda yan yana oluştu","Bir asteroit kümesinin birleşmesiyle"]', 1, 'Dev Çarpışma Hipotezi: Theia teğet çarptı, saçılan enkaz halkasından Ay birleşti.', 'dunya'),
    ('Bilinen gezegenler arasında yalnızca Dünya''da olan özellik hangisidir?', '["Aktif levha tektoniği","Atmosfer","Uydu","Manyetik alan"]', 0, 'Aktif levha tektoniği yalnızca Dünya''da bilinir; karbon–iklim döngüsünü çevirir.', 'dunya'),
    ('Hücrelerimizdeki mitokondrinin kökeni nedir?', '["Bir virüs","Cansız bir kristal","Çekirdeğin bir parçası","Bir zamanlar serbest yaşayan bir bakteri"]', 3, null, 'endosimbiyoz'),
    ('Endosimbiyotik kuramı kanıtlarla savunup kabul ettiren bilim insanı kimdir?', '["Louis Pasteur","Charles Darwin","Lynn Margulis","Gregor Mendel"]', 2, null, 'endosimbiyoz'),
    ('Aşağıdakilerden hangisi mitokondrinin bakteriyel kökenine kanıt DEĞİLDİR?', '["70S bakteriyel ribozomları","Düz, kromozomlara paketlenmiş DNA''sı","Çifte zarı","Halkasal kendi DNA''sı"]', 1, null, 'endosimbiyoz'),
    ('Mitokondri neden artık hücreden bağımsız yaşayamaz?', '["Çok yaşlandığı için","Genlerinin çoğu çekirdeğe taşındığı için (gen transferi)","Oksijenden korktuğu için","Donduğu için"]', 1, null, 'endosimbiyoz'),
    ('Karmaşık (ökaryotik) hücrenin konağı büyük olasılıkla hangi gruptandı?', '["Mantarlar","Virüsler","Asgard arkeleri","Yeşil algler"]', 2, null, 'endosimbiyoz'),
    ('Endosimbiyozun karmaşık yaşamı mümkün kılmasının temel nedeni nedir?', '["Enerji üretimini iç zarlara taşıyıp enerji bariyerini aştığı için","Sıcaklığı düşürdüğü için","Renk kattığı için","Hücreyi küçülttüğü için"]', 0, null, 'endosimbiyoz'),
    ('Kloroplastın atası hangi bakteri grubudur?', '["Siyanobakteriler","Rickettsia","Salmonella","Spiroketler"]', 0, null, 'endosimbiyoz'),
    ('2024''te keşfedilen, azot bağlayan dördüncü büyük organel tipinin adı nedir?', '["Lizozom","Ribozom","Kromatofor","Nitroplast"]', 3, null, 'endosimbiyoz'),
    ('İkincil endosimbiyozda kloroplastın 3-4 zarla çevrili olmasının sebebi nedir?', '["Radyasyon","Tesadüf","Çok yaşlı olması","Bir ökaryotun, içinde zaten kloroplast olan başka bir ökaryotu yutması"]', 3, null, 'endosimbiyoz'),
    ('Perde 3''teki sayılara göre kuşatmayı esas ne belirledi?', '["Urban''ın topu tek başına surları yıktı","Top ile gece onarımı arasındaki yarış","Açlık; deniz kapalıydı","Merdivenli hücumlar"]', 1, 'Top günde ancak 3–7 kez ateşlenebiliyordu (namlu ısınıp çatlıyordu); gündüz açılan gediği savunmacılar gece dolduruyordu. Kuşatma bir yarıştı ve haftalarca savunma kazandı — topu top bitirmedi.', 'fatih'),
    ('Boğazkesen (Rumeli Hisarı) ne zaman ve neyi yaptı?', '["Kuşatma sırasında; moral verdi","1452''de; Boğaz''ı kapatıp şehrin gıdasını kesti","1453''te; surları dövdü","Fetihten sonra; şehri korudu"]', 1, 'Kale 1452''de, dört buçuk ayda kuruldu ve Boğaz''ı kapattı. Karadeniz''den gelen buğday gemileri iki kalenin topu arasından geçmek zorunda kaldı; kuşatma fiilen aylar önce, bir binayla başladı.', 'fatih'),
    ('22 Nisan 1453 gecesi Osmanlı gemileri Haliç''e nasıl girdi?', '["Zinciri kırarak","Karadan, Galata sırtından yaklaşık 1,5 km yürütülerek","Gizli bir tünelden","Şafakta baskınla"]', 1, 'Zincir kırılamadığı için aşıldı: yağlanmış kütükler üzerinde, öküz ve insan gücüyle yaklaşık otuz gemi tek gecede tepeden aşırıldı. Zincir yerinde kaldı ama işlevi kalmadı.', 'fatih'),
    ('Fatih''in aldığı "Kayser-i Rûm" unvanının mantığı neydi?', '["Halifelik iddiası","Başkenti tutan imparatordur — fetih hakkı","Bizans hanedanından soy iddiası","Papalığın onayı"]', 1, 'Konstantinopolis 330''dan beri Roma''nın başkentiydi; başkenti tutan imparator sayılırdı. Batı çoğunlukla reddetti, ama sultanın yeniden kurduğu Patrikhane tanıdı. Augustus''un kurduğu makamın çizgisi buraya bağlanır.', 'fatih'),
    ('Hünkâr Çayırı''ndaki ölümün sebebi kaynaklarda nasıl geçer?', '["Kesin: savaşta öldü","Kesin: zehirlendi","Belirsiz: gut/hastalık kayıtlı, zehir iddiası kanıtlanmamış","Kesin: yaşlılık"]', 2, 'Fatih gut hastasıydı ve 49 yaşında bir seferin başında öldü. Heywood zehirlenmeye dair dolaylı deliller olduğunu söyler ama "kanıtlanamaz" da ekler. Sıfat değil, sayı: kesinlik yok, ihtimaller var.', 'fatih'),
    ('Kütle ile ağırlık arasındaki temel fark nedir?', '["Kütle madde miktarıdır (hep aynı), ağırlık yerçekimi kuvvetidir (gezegene göre değişir)","Ağırlık her yerde aynıdır","Kütlenin birimi newton","Aynı şeydir"]', 0, 'Kütlen Ay''da da aynıdır; ama daha az çekildiğin için ağırlığın azalır.', 'fizik-101'),
    ('F = m·a neyi söyler?', '["Kütle = kuvvet × ivme","İvme = kuvvet × kütle","Kuvvet = kütle bölü ivme","Kuvvet = kütle × ivme"]', 3, 'Aynı kuvvet, daha büyük kütleye daha küçük ivme verir.', 'fizik-101'),
    ('1 Newton nedir?', '["1 joule enerji","1 metre yol","1 kg kütle","1 kg''ı 1 m/s² ivmelendiren kuvvet"]', 3, 'Newton kuvvetin birimidir: 1 N = 1 kg·m/s². Bir elma ~1 N ağırlığındadır.', 'fizik-101'),
    ('Hız ile sürat farkı nedir?', '["Hız sadece arabalar için","Fark yoktur","Hız yön içerir (vektör), sürat yalnızca büyüklüktür (skaler)","Sürat daha hızlıdır"]', 2, '''Kuzeye 20 m/s'' hız; ''20 m/s'' sürattir.', 'fizik-101'),
    ('Çarpışmada momentum ne olur?', '["Yok olur","Korunur — toplam momentum önce ve sonra aynıdır","İkiye katlanır","Sadece hızlı cisimde kalır"]', 1, 'Momentum = kütle × hız; kapalı sistemde toplamı sabittir.', 'fizik-101'),
    ('Yukarıdaki top aşağı inerken enerjisine ne olur?', '["Potansiyel enerji kinetik enerjiye dönüşür; toplam sabit kalır","İkiye katlanır","Isıya dönüşüp biter","Yok olur"]', 0, 'Enerji yoktan var olmaz; yalnızca biçim değiştirir (enerjinin korunumu).', 'fizik-101'),
    ('Bir alan adını (basementonfire.com) IP adresine çeviren sistem hangisidir?', '["DNS","TCP","MAC","HTTP"]', 0, null, 'internet'),
    ('OSI modelinde yönlendiriciler (router) hangi katmanda çalışır?', '["Veri Bağı (2)","Ağ (3)","Taşıma (4)","Fiziksel (1)"]', 1, null, 'internet'),
    ('Hangi protokol hız için güvenilirlikten ödün verir (video/oyun)?', '["UDP","HTTPS","FTP","TCP"]', 0, null, 'internet'),
    ('HTTPS''teki "S" neyi sağlar?', '["Daha çok reklam","Sıkıştırma","Daha hızlı yükleme","TLS ile şifreleme"]', 3, null, 'internet'),
    ('MAC adresi neyi tanımlar?', '["Ağdaki mantıksal konumu","Cihazın fiziksel ağ kartını","Web sitesini","Port numarasını"]', 1, null, 'internet'),
    ('TCP bağlantısı kaç adımlı "el sıkışma" ile kurulur?', '["1","2","3","4"]', 2, null, 'internet'),
    ('"Kaligrafi" kelimesi hangi köklerden gelir?', '["Arapça hat + hüsn","Çince shū + fǎ","Latince calidus + grafia","Yunanca kallos (güzellik) + graphein (yazmak)"]', 3, null, 'kaligrafi'),
    ('Kaligrafi ile tipografi arasındaki temel fark nedir?', '["Tipografi fırçayla yapılır","İkisi aynıdır","Tipografi önceden tasarlanmış harf kalıplarını (font) düzenler","Kaligrafi sadece bilgisayarda yapılır"]', 2, null, 'kaligrafi'),
    ('İslam hattını "göz kararı"ndan çıkarıp matematiksel orana oturtan kişi kimdir?', '["Hâfız Osman","Yâkût el-Musta''sımî","İbn Mukle","Şeyh Hamdullah"]', 2, null, 'kaligrafi'),
    ('Osmanlı hat ekolünün kurucusu kabul edilen hattat kimdir?', '["Mustafa Râkım","Şeyh Hamdullah","Sâmi Efendi","Ahmed Karahisârî"]', 1, null, 'kaligrafi'),
    ('Doğu Asya kaligrafisinin temel aracı nedir?', '["Geniş uçlu çelik kalem","Fırça","Esnek sivri uç","Kamış kalem"]', 1, null, 'kaligrafi'),
    ('Çin yazısında başlangıç için en uygun, bugünkü matbaa ve dijital yazının temeli olan stil hangisidir?', '["Yürüyen yazı (xíngshū)","Mühür yazısı (zhuànshū)","Bitişik yazı (cǎoshū)","Standart / düz yazı (kǎishū)"]', 3, null, 'kaligrafi'),
    ('Modern (Batı) kaligrafinin babası kabul edilen, geleneği yeniden canlandıran isim kimdir?', '["Edward Johnston","Platt Rogers Spencer","Johannes Gutenberg","Ludovico Arrighi"]', 0, null, 'kaligrafi'),
    ('Sivri esnek uçta "altın kural" nedir?', '["Yukarı çıkarken ince (baskısız), aşağı inerken kalın (baskılı)","Yukarı kalın, aşağı ince","Baskı hiç değişmez","Hep aynı baskı"]', 0, null, 'kaligrafi'),
    ('Geniş uçlu (broad-edge) kalemde ince-kalın farkı neyden gelir?', '["Mürekkebin renginden","Kâğıdın türünden","Baskıdan","Ucun sabit açısından"]', 3, null, 'kaligrafi'),
    ('Kanuni’nin Viyana seferinde (1529) yürüyüş kaç gün, kuşatma kaç gün sürdü?', '["140 gün yürüyüş, 19 gün kuşatma","19 gün yürüyüş, 140 gün kuşatma","İkisi de yaklaşık 80 gün","60 gün yürüyüş, 90 gün kuşatma"]', 0, '10 Mayıs’ta İstanbul’dan çıkıldı, 27 Eylül’de Viyana önlerine varıldı, 16 Ekim’de kuşatma kaldırıldı. Seferin neredeyse tamamı yoldu.', 'kanuni'),
    ('Mohaç Muharebesi yaklaşık ne kadar sürdü?', '["İki saat","İki gün","İki hafta","İki ay"]', 0, '29 Ağustos 1526. Ordunun oraya varması 128 gün sürdü; muharebe yaklaşık iki saatte bitti.', 'kanuni'),
    ('Dört taçlı Venedik miğferini kim sipariş etti ve kaç taçlıydı?', '["İbrahim Paşa · dört taç","Süleyman’ın kendisi · üç taç","Papa’nın elçisi · beş taç","Sokollu Mehmed Paşa · iki taç"]', 0, '1532’de İbrahim Paşa’nın siparişiyle Venedik’te yapıldı. Papa’nın tiarası üç katlıydı; miğferde dört taç vardı — sayıyla üstünlük iddiası.', 'kanuni'),
    ('"Kanunî" sıfatı ne anlama gelir?', '["Şeriatın yanında işleyen örfî hukuku (kanun) düzenlemesi","Şeriatı kaldırıp yerine laik kanun koyması","Avrupa kanunlarını tercüme ettirmesi","Kanunları bizzat kendi eliyle yazması"]', 0, 'Osmanlı’da şeriat ve kanun yan yana çalışır. Kanunî, örfî hukuku düzenleyip şer’î çerçeveye oturtan taraftır; bu uyumu kuran isim Şeyhülislam Ebussuud Efendi’dir.', 'kanuni'),
    ('Şehzade Mustafa otağa girmeseydi ne olurdu?', '["Çağrıya uymamak, suçlandığı isyanın ispatı sayılırdı","Kanunen serbest kalırdı","Sancağına döner ve mesele kapanırdı","Divan onu yargılamak zorunda kalırdı"]', 0, 'Üç kapı da aynı yere çıkıyordu: girmek de girmemek de silahlı girmek de. Makalenin ifadesiyle bu bir bilmece değil, durumun kendisiydi.', 'kanuni'),
    ('Kardeş katli maddesiyle ilgili tartışma nedir?', '["Maddenin Fatih’e ait olup olmadığı: nüshalar geç tarihli","Maddenin hiç var olmadığı","Maddenin Kanuni tarafından yazıldığı","Maddenin yalnız Avrupa kaynaklarında geçtiği"]', 0, 'Metin Fatih Kanunnâmesi olarak bilinir ama elimizdeki nüshalar sonraki yüzyıllardan. Otantik diyen de var, sonradan eklendiğini savunan da; üçüncü bir görüş uygulamanın zaten Fatih’ten önce var olduğunu söyler.', 'kanuni'),
    ('Kanuni öldükten sonra ne oldu?', '["Ölümü ordudan gizlendi, hükümler onun tuğrasıyla çıkmaya devam etti","Ordu hemen İstanbul’a döndü","Sefer o gece iptal edildi","Yeni padişah ertesi sabah orduya katıldı"]', 0, 'Vezir-i âzam Sokollu Mehmed Paşa ölümü sakladı; ceset tahnit edildi, tahtırevan yola devam etti, divan toplandı ve aynı tuğra basılmaya devam etti.', 'kanuni'),
    ('Bu makalenin merkez iddiası nedir?', '["Kanunu yazan adam kendi kanununun dışında kaldı; makine ona işlemedi","Kanuni Osmanlı’nın en zalim padişahıydı","Osmanlı hukuku tamamen keyfîydi","Batı kaynakları Doğu kaynaklarından daha güvenilirdir"]', 0, 'Makale ne övgü ne yergi: işleyen bir düzenin, onu kuran adamın üstüne kapanmadığını gösteriyor. Sıfat değil, sayı.', 'kanuni'),
    ('Süperpozisyon nedir?', '["Ölçülene kadar birbirini dışlayan ihtimallerin bir arada bulunması","Parçacığın iki parçaya bölünmesi","Bir ölçüm hatası","Parçacığın çok hızlı olması"]', 0, 'Havada dönen yazı-tura gibi: henüz ne yazı ne tura, ikisinin ihtimali aynı anda.', 'kuantum-olumsuzlugu'),
    ('Kopenhag yorumunda ölçüm ne yapar?', '["Parçacığı yok eder","Evreni ikiye ayırır","Hiçbir şey","Dalga fonksiyonunu çökertir; tek bir sonuç gerçek olur"]', 3, 'Sayısız ihtimalden yalnızca biri gerçek olur; hangisi olacağını Born kuralı belirler.', 'kuantum-olumsuzlugu'),
    ('Çok Dünyalı Yorum''a göre ölçümde ne olur?', '["Her ihtimal ayrı bir dalda/evrende gerçekleşir; gözlemci de çatallanır","Sadece en olası sonuç gerçekleşir","Dalga çöker","Hiçbir ihtimal gerçekleşmez"]', 0, 'Everett: hiçbir şey çökmez; evren her karar anında sessizce dallanır.', 'kuantum-olumsuzlugu'),
    ('Kuantum ölümsüzlüğünün özü nedir?', '["Bedenin hiç yaşlanmaması","Öznel deneyimin hep hayatta kaldığın dalı takip etmesi","Ölümün tamamen imkânsız olması","Bilincin başka bedene geçmesi"]', 1, 'Dışarıdan ölürsün; içeriden asla — çünkü öldüğün dalda bunu fark edecek bir ''sen'' kalmaz.', 'kuantum-olumsuzlugu'),
    ('Fizikçilerin en temel itirazı nedir?', '["Çok pahalı bir deney","Matematik yanlış","İddia dışarıdan yanlışlanamaz; kanıtlamak için ölmen gerekir","Kuantum mekaniği yanlış"]', 2, 'Yalnızca birinci şahsa özel, test edilemez bir ''ya öyleyse?'' sorusudur.', 'kuantum-olumsuzlugu'),
    ('Adam Fawer''ın Mobius''u bu fikri neye çevirir?', '["Bir korku filmine","Bir matematik problemine","Bir fizik ders kitabına","Bir pişmanlık makinesine — geçmişi değiştirme sorusuna"]', 3, 'Fizik cevabı verir; roman bedeli gösterir: elimizde her şeyi geri alma şansı olsa daha iyisini yapar mıydık?', 'kuantum-olumsuzlugu'),
    ('Mol temelde nedir?', '["Bir hacim birimi (litre gibi)","Bir sayma birimi — 6,022 × 10²³ tane","Bir sıcaklık birimi","Bir kütle birimi (gram gibi)"]', 1, 'Mol, ''düzine'' gibi bir sayma birimidir; sadece temsil ettiği sayı akıl almaz büyüktür.', 'mol'),
    ('36 gram su (M = 18 g/mol) kaç moldür?', '["18 mol","36 mol","0,5 mol","2 mol"]', 3, 'n = m ÷ M = 36 ÷ 18 = 2 mol. Sonra 2 × 6,022×10²³ = 1,2×10²⁴ molekül.', 'mol'),
    ('1 mol hidrojen ile 1 mol altının tanecik sayısı için hangisi doğru?', '["İkisinde de aynı sayıda tane var (6,022×10²³), kütleleri farklı","Karşılaştırılamaz","Altında daha çok tane var","Hidrojende daha çok tane var"]', 0, 'Sayı hep aynıdır; altın atomu daha ağır olduğu için kütlesi (197 g) hidrojeninkinden (1 g) fazladır.', 'mol'),
    ('Periyodik tablodaki ''bağıl atom kütlesi'' sayısı ne işe yarar?', '["Elektron sayısını verir","Kaynama noktasıdır","Atomun boyunu verir","Aynı zamanda o elementin gram cinsinden molar kütlesidir"]', 3, 'Karbon 12 → 1 mol karbon 12 gram. Birimler tam da bunu sağlayacak şekilde tanımlanmıştır.', 'mol'),
    ('Normal Koşullar''da 1 mol ideal gaz kaç litre yer kaplar?', '["22,4 litre","Gaza göre değişir","1 litre","18 litre"]', 0, 'Avogadro yasası: molekülü ne olursa olsun, N.K.''da 1 mol gaz = 22,4 L.', 'mol'),
    ('Tepkimelerdeki mol oranı matematiğinin adı nedir?', '["Elektroliz","Termodinamik","Stokiyometri","Kinetik"]', 2, '2H₂ + O₂ → 2H₂O denklemi 2:1:2 mol oranını verir; tarif matematiği gibi.', 'mol'),
    ('1665–66 “Mucize Yılları”nda Newton''ın YAPMADIĞI şey hangisidir?', '["Kütleçekimin ilk adımlarını atmak","Buharlı makineyi icat etmek","Kalkülüsü icat etmek","Beyaz ışığın renklere ayrıldığını keşfetmek"]', 1, 'Buharlı makine Newton''a ait değildir. Diğer üçünü o olağanüstü 18 ayda başardı.', 'newton'),
    ('F = m·a denklemi neyi söyler?', '["İvme = kuvvet × kütle","Kuvvet = kütle ÷ ivme","Kuvvet = kütle × ivme","Kütle = kuvvet × ivme"]', 2, 'Bir şeyi ne kadar sert itersen o kadar hızlanır; ama ne kadar ağırsa o kadar zor hızlanır.', 'newton'),
    ('Evrensel kütleçekimde iki cisim arası mesafe 2 katına çıkarsa çekim kuvveti ne olur?', '["Dörtte bire iner","Değişmez","2 katına çıkar","Yarıya iner"]', 0, 'Kuvvet mesafenin KARESİYLE azalır (ters-kare): 2× mesafe → 1/4 kuvvet.', 'newton'),
    ('Newton servetini hangi olayda kaybetti?', '["Kalpazanlık davası","Veba salgını","Büyük Londra Yangını","Güney Denizi Balonu"]', 3, 'Balon patlamadan tepe noktasında geri girdi (bir tür FOMO) ve büyük kayıp yaşadı.', 'newton'),
    ('Bugün Newton''ın ARTIK tek başına kullanmadığımız fikri hangisidir?', '["Yansıtmalı teleskop","F = m·a","Kalkülüs","Mutlak (değişmez) uzay ve zaman"]', 3, 'Einstein, uzay ve zamanın gözlemciye göre değiştiğini (göreli olduğunu) gösterdi.', 'newton'),
    ('Görelilik ve kuantum fiziği, Newton''ı...', '["Yalnızca matematikte değiştirdi","Tamamen çürüttü","Çürütmez; kapsar (düşük hızda Newton''a indirgenir)","Hiç etkilemedi"]', 2, 'Hız düşük, kütleçekim zayıfken Einstein''ın denklemleri tam tamına Newton''a dönüşür.', 'newton'),
    ('Mendeleyev’in yaptığı tahminlerin isabet oranı neydi?', '["Neredeyse tamamı tuttu","%50’nin altında","Tam olarak yarısı","Hiçbiri tutmadı"]', 1, 'On tahmini karşılığını buldu, on dördü hiç bulunamadı. Lente (2019) bunu "%50’den kötü" diye özetliyor.', 'periyodik-tablo'),
    ('Periyodik tablonun ilk satırında neden sadece iki element var?', '["Hidrojen ve helyum en hafifleri olduğu için","1p orbitali diye bir şey olmadığı için","Tarihsel bir gelenek","Yer kazanmak için"]', 1, 'ℓ ≤ n−1 kısıtı yüzünden n = 1 için yalnız s orbitali vardır. Şekil bir tercih değil, bir sonuç.', 'periyodik-tablo'),
    ('Lantanitlerin tablonun altında ayrı durmasının sebebi nedir?', '["Kimyasal olarak farklı oldukları için","Sadece sayfaya sığdırmak için","Radyoaktif oldukları için","Sonradan keşfedildikleri için"]', 1, 'Tamamen tipografik. f bloğu aslında 2. ve 3. grubun arasına oturur; 32 sütunu 18 sütuna indirmek için alta basılıyor.', 'periyodik-tablo'),
    ('IUPAC 3. grubun altına ne yazılacağına karar verdi mi?', '["Evet, lantan","Evet, lutesyum","Hayır, tartışma sürüyor","Grup 3 diye bir şey yok"]', 2, '2021 geçici raporu birebir "objektif bir hakem yok" diyor. Uzlaşı olarak Lu öneriliyor ama karar bağlanmadı.', 'periyodik-tablo'),
    ('Oganesson (118) hakkında hangisi doğru?', '["Kararlı bir soy gazdır","Oda sıcaklığında katı olması bekleniyor","Doğada bulunur","En bol soy gazdır"]', 1, 'Üç atom üretildi, yarı ömrü 0,7 ms. Teorik hesaplar katı ve yarı iletken olduğunu söylüyor — ne soy ne gaz.', 'periyodik-tablo'),
    ('Pirus hangi krallığın kralıydı?', '["Epir","Sparta","Kartaca","Makedonya"]', 0, null, 'pirus'),
    ('"Pirus zaferi" ne anlama gelir?', '["Kazanana yenilgi kadar pahalıya patlayan zafer","Hile ile kazanılan zafer","Savaşsız kazanılan zafer","Kolay ve ucuz bir zafer"]', 0, null, 'pirus'),
    ('Romalılar ilk kez hangi savaşta savaş fili gördü?', '["Beneventum","Herakleia","Cannae","Asculum"]', 1, null, 'pirus'),
    ('Pirus kimi idol edinmiş, kime uzaktan akrabaydı?', '["Leonidas","Hannibal","Jül Sezar","Büyük İskender"]', 3, null, 'pirus'),
    ('Pirus nasıl öldü?', '["Savaş meydanında kahramanca","Zehirlenerek","Argos''ta bir kiremitle","Hastalıktan"]', 2, null, 'pirus'),
    ('Cineas diyaloğunun ana fikri nedir?', '["Daha çok fethetmek gerekir","Hırsın sonu yoktur; huzur için fethe gerek yok","Filler savaşı kazandırır","Roma yenilmezdir"]', 1, null, 'pirus'),
    ('"Yarılanma süresi 1.600 yıl" ne demek?', '["Her atom 1.600 yıl yaşar","Atomların yarısı 1.600 yılda bozunur; kalanın şansı hiç değişmez","Bozunma 1.600 yılda tamamen durur","Atom 1.600 yıl sonra yarı boyuta iner"]', 1, 'Atomların hafızası yok. Ayakta kalan atomun önümüzdeki 1.600 yılda bozunma şansı hâlâ tam olarak yüzde elli — yorulmaz, yaşlanmaz.', 'radyoaktivite'),
    ('Bir alfa yayıcısı ne zaman gerçekten tehlikelidir?', '["Elinizde tuttuğunuzda","Yanından geçtiğinizde","Yuttuğunuzda ya da soluduğunuzda","Hiçbir zaman, kâğıt durdurur"]', 2, 'Alfa dışarıda zararsız (kâğıt, deri durdurur), içeride acımasız. Litvinenko polonyum-210''u bir bardak çayla içti.', 'radyoaktivite'),
    ('Vücudunuzda şu an saniyede kaç atom çekirdeği parçalanıyor?', '["Sıfır — insan radyoaktif değildir","Birkaç tane","Yaklaşık 7.000–8.000","Milyarlarca"]', 2, 'Büyük kısmı potasyum-40, gerisi ağırlıkla karbon-14. Onları ayıklamanın imkânı yok: kimyasal olarak normal potasyum ve karbonla tıpatıp aynılar.', 'radyoaktivite'),
    ('Yarılanma süresini hızlandırmak için ne yapabilirsiniz?', '["Isıtmak","Basınç uygulamak","Kimyasal tepkimeye sokmak","Hiçbiri — değiştirilemez"]', 3, 'Bozunma çekirdeğin içinde olur; sıcaklık, basınç ve kimya elektronları ilgilendirir. Radyoaktif atık probleminin can sıkıcılığı tam olarak bu: onu ikna edemezsiniz.', 'radyoaktivite'),
    ('Gama ışınını durdurmak için ne gerekir?', '["Bir yaprak kâğıt","Bir alüminyum folyo","Kurşun, kalın beton ya da birkaç metre su","Hiçbir şey durduramaz"]', 2, 'Gama kütlesiz bir fotondur, maddenin arasından süzülür. Çernobil''de kurşunun helikopterlerden dökülme sebebi buydu.', 'radyoaktivite'),
    ('Oklo (Gabon) neden şaşırtıcıydı?', '["Orada uranyum bulunmadı","Doğal bir nükleer reaktör 1,7 milyar yıl önce kendiliğinden çalışmıştı","Uranyum yapay olarak üretilmişti","Bir meteor çarpmıştı"]', 1, 'Yeraltı suyu moderatör görevi gördü; reaktör ısınınca su buharlaştı, tepkime yavaşladı, kaya soğuyunca su geri geldi. Kendi kendini düzenleyen bir sistem, yüz binlerce yıl.', 'radyoaktivite'),
    ('Fazladan bir muz yemek vücudunuzun radyoaktivitesini kalıcı olarak artırır mı?', '["Evet, potasyum birikir","Hayır — vücut potasyum seviyesini sabit tutar, fazlası idrarla gider","Evet ama sadece bir gün","Muz radyoaktif değildir"]', 1, 'Muz eşdeğer dozu, gerçek bir birikimden çok bir pedagoji numarasıdır: "radyasyon" kelimesinin kendi başına bir felaket ilanı olmadığını anlatır.', 'radyoaktivite'),
    ('Roma''nın efsanevi kurucusu hangi hayvan tarafından emzirildiği söylenir?', '["Kartal","Dişi Kurt","Aslan","Boğa"]', 1, null, 'rome'),
    ('12 Levha Kanunu hangi meydana asıldı?', '["Capitoline Tepesi","Colosseum","Pantheon","Forum Romanum"]', 3, null, 'rome'),
    ('Julius Caesar''ın Rubicon Nehrini geçmesi neyi sembolize ediyordu?', '["Zafer kutlaması","Senatoya katılım","İç savaş başlatmak","Galya''ya sefer"]', 2, null, 'rome'),
    ('Spartaküs hangi sınıfı temsil ediyordu?', '["Köleler ve Gladyatörler","Ordu generalleri","Patricii","Senato"]', 0, null, 'rome'),
    ('Belgeye göre bir akım tipik olarak neyle doğar?', '["Beş “motor”dan (para, teknoloji, siyaset, kurum reddi, paradigma) en az ikisinin kesişiminde","Sadece yeni bir boya icat edilince","Devlet emriyle","Tek bir dâhinin farklı resim yapma isteğiyle"]', 0, 'Hiçbir akım tek motorla çıkmaz; genelde para, teknoloji, siyaset, kurum reddi ve paradigma kaymasından birkaçı üst üste biner.', 'sanat-akimlari'),
    ('Hollanda Altın Çağı neden “ekonomi belirler”in en net örneğidir?', '["Yeni bir boya icat edildiği için","Kral resim sevdiği için","Devlet ressamlara maaş bağladığı için","Protestan ikonoklazm en büyük müşteriyi (kilise) silince açık piyasa ve tür uzmanlaşması doğduğu için"]', 3, 'Kilise duvarı gidince sanatçı sipariş beklemeyip üretip sattı; manzara, natürmort, iç mekân gibi türler bu piyasadan doğdu.', 'sanat-akimlari'),
    ('Duchamp’ın 1917’de pisuarı “Çeşme” adıyla sergiye göndermesi hangi soruyu değiştirdi?', '["“Bu ne kadar pahalı?”","“Bu iyi mi?” yerine “Bu neden sanat sayılıyor, kim karar veriyor?”","“Bu nasıl yapıldı?”","Hiçbirini"]', 1, 'Hazır-nesne, kavramsal sanatın, enstalasyonun ve kurum eleştirisinin başlangıcıdır.', 'sanat-akimlari'),
    ('Sanatın merkezinin Paris’ten New York’a geçmesinin asıl mekanizması neydi?', '["Reklamın icadı","Amerikalıların daha yetenekli olması","Totaliter rejimlerden kaçan Avrupalı sanatçıların ABD’ye kitlesel göçü","Yeni bir müze açılması"]', 2, 'Estetik bir zafer değil, bir göç dalgası: Mondrian, Ernst, Breton, Gropius, Mies, Albers… “Avrupa’nın kaybı, Amerika’nın kazancı.”', 'sanat-akimlari'),
    ('Fütürizm neden “ilk pazarlama-avangardı” sayılır?', '["İlk soyut resmi yaptığı için","Manifestosunu bir gazetenin (Le Figaro) birinci sayfasında yayımladığı için","En çok tablo sattığı için","İnterneti kullandığı için"]', 1, 'Fütürizm kendini medya üzerinden kurdu; aynı zamanda militarizmi yücelterek avangardın siyaseten nötr olmadığını da gösterdi.', 'sanat-akimlari'),
    ('Linda Nochlin’in 1971 denemesi tartışmayı nereye kaydırdı?', '["Yetenekten kuruma (eğitim, akademi, erişim)","Renkten çizgiye","Resimden heykele","Avrupa’dan Amerika’ya"]', 0, '“Neden hiç büyük kadın sanatçı olmadı?” sorusu, eksikliğin yetenekte değil kurumsal engellerde olduğunu gösterdi.', 'sanat-akimlari'),
    ('Alesia’da Caesar aynı anda hem kuşatan hem kuşatılan taraf oldu. Bunu nasıl başardı?', '["Tepeyi ele geçirip yükseklik avantajı aldı","İki ayrı sur inşa etti: biri içe, biri dışa dönük","Nehri saptırıp kaleyi susuz bıraktı","Ordusunu ikiye bölüp iki cephede savaştı"]', 1, 'İç hat 11 Roma mili (~16 km), dış hat 14 mil (~21 km). İçeride 80.000 Galyalı, dışarıda bir kurtarma ordusu, ortada iki duvar arasına sıkışmış Caesar.', 'sezar'),
    ('Caesar’ın cesedindeki 23 yaradan kaçı ölümcüldü?', '["Hepsi","Yaklaşık yarısı","Yalnızca biri","Hiçbiri — kan kaybından öldü"]', 2, 'Hekim Antistius (tarihe geçen ilk otopsi raporu) yalnızca ikinci yaranın — göğse gelenin — öldürücü olduğunu bildirdi. Bu, cinayetin bir suikasttan çok bir sürü davranışı olduğunu gösterir: herkesin bıçağını sokması gerekiyordu.', 'sezar'),
    ('Caesar iç savaşı kazandıktan sonra düşmanlarına ne yaptı?', '["Sulla gibi ölüm listeleri astı","Hepsini sürgüne yolladı","Affetti — bazılarını terfi bile ettirdi","Servetlerine el koyup serbest bıraktı"]', 2, 'Ve bu bir tuzaktı. Birini affetmek için önce onu öldürebilecek konumda olmanız gerekir. Caesar herkesi affederek Roma’nın tüm seçkinlerini kendisine borçlu hâle getirdi — ve borçlu olmak, eşit olmamaktır.', 'sezar'),
    ('“Et tu, Brute?” sözü nereden geliyor?', '["Suetonius’tan","Plutarkhos’tan","Caesar’ın kendi metninden","Shakespeare’den"]', 3, 'Suetonius, Caesar’ın hiçbir şey söylemeden öldüğünü yazar. Yunanca “sen de mi, evladım?” sözünü yalnızca başkalarının aktardığı bir rivayet olarak kaydeder — ve kendisi buna inanmaz.', 'sezar'),
    ('Suikastçılar Caesar’ı öldürdükten sonra Cumhuriyet’e ne oldu?', '["Yeniden kuruldu ve 200 yıl daha yaşadı","Kısa bir kaosun ardından Senato yönetimi geri aldı","Bir daha geri gelmedi; Caesar’ın evlatlık oğlu ilk imparator oldu","Roma ikiye bölündü"]', 2, 'Suikastçıların bir sonraki adım için planı yoktu. On üç yıl daha iç savaş sürdü; Actium’da kazanan Octavianus, “Augustus” adını alıp Roma’nın ilk imparatoru oldu.', 'sezar'),
    ('Takyon nedir?', '["Varsayımsal, hep ışıktan hızlı bir parçacık","Bir tür ışık","Kara delik çekirdeği","Işıktan yavaş bir parçacık"]', 0, null, 'takyon'),
    ('Bir takyonun (varsa) kütlesi nasıl tanımlanır?', '["Sonsuz","Sıfır","Negatif","Sanal (imajiner)"]', 3, null, 'takyon'),
    ('Takyonlar neden nedenselliği (sebep-sonucu) tehdit eder?', '["Kara deliklerden çıktıkları için","Çok ağır oldukları için","Işıktan hızlı bilgi → kendi geçmişine mesaj göndermek","Görünmez oldukları için"]', 2, null, 'takyon'),
    ('2011 OPERA "ışıktan hızlı nötrino" sonucunun gerçek sebebi neydi?', '["Gerçek takyonlar","Gevşek bir fiber-optik kablo","Güneş patlaması","Yazılım virüsü"]', 1, null, 'takyon'),
    ('Aşağıdakilerden hangisi ışıktan hızlı olabilir ama kuralı BOZMAZ?', '["Duvardaki bir gölge","Bir uzay gemisi","Bir foton","Bir elektron"]', 0, null, 'takyon'),
    ('Modern fizikte (kuantum alan kuramı) "takyon" çoğunlukla neyi ifade eder?', '["Yeni bir enerji türü","Antimadde","Gerçek ışıktan hızlı parçacık","Bir alanın kararsızlığı (negatif kütle-kare)"]', 3, null, 'takyon'),
    ('Tardigradların halk arasındaki adı nedir?', '["Deniz yıldızı","Su ayısı","Toprak solucanı","Cam böceği"]', 1, null, 'tardigrad'),
    ('Kuruyunca girdikleri, metabolizmayı neredeyse durduran hale ne denir?', '["Tun hali (kriptobiyoz)","Metamorfoz","Fotosentez","Hibernasyon"]', 0, null, 'tardigrad'),
    ('Tardigradlar yaklaşık hangi sıcaklık aralığında hayatta kalabilir?', '["−272°C – 150°C","−10°C – 60°C","sadece oda sıcaklığı","0°C – 40°C"]', 0, null, 'tardigrad'),
    ('DNA''larını radyasyondan koruyan özel proteinin adı nedir?', '["Klorofil","Hemoglobin","Dsup","Keratin"]', 2, null, 'tardigrad'),
    ('2007''de tardigradlar ilk kez nerede hayatta kaldı?', '["Güneş''te","Reaktör çekirdeğinde","Volkan içinde","Doğrudan uzay boşluğunda"]', 3, null, 'tardigrad'),
    ('Tun halinde suyunun ne kadarını kaybederler?', '["hiç","%10","%50","%95''ten fazla"]', 3, null, 'tardigrad')
) as v(question, options, correct_index, explanation, article_slug)
where not exists (
